1	/* ═══════════════════════════════════════════
2	   Indicator part classes (item-indicator--* convention)
3	   ARIA attributes drive state — no JS class toggle needed.
4	   All values: design tokens only, no raw numbers.
5	   Specificity 0 via :where() — module.css overrides freely.
6	   ═══════════════════════════════════════════ */
7	
8	/* ── Chevron ── */
9	
10	:where([data-aria-container] .item-chevron),
11	:where(details .item-chevron) {
12	  display: inline-flex;
13	  align-items: center;
14	  justify-content: center;
15	  color: var(--text-muted);
16	  font-size: var(--type-body-size);
17	  opacity: 0.65;
18	  transition: transform var(--motion-normal-duration) var(--motion-normal-easing);
19	}
20	
21	:where([data-aria-container] .item-chevron--expand),
22	:where(details .item-chevron--expand) {
23	  width: var(--icon-xs);
24	  flex-shrink: 0;
25	  text-align: center;
26	}
27	
28	:where([data-aria-container] .item-chevron--tree) {
29	  width: var(--icon-sm);
30	  flex-shrink: 0;
31	}
32	
33	/* Expanded state: details[open] drives rotation (standalone context) */
34	:where(details[open] > summary .item-chevron) {
35	  transform: rotate(90deg);
36	}
37	
38	/* ── Checkbox indicator (square) ── */
39	
40	:where([data-aria-container] .item-indicator--checkbox) {
41	  flex-shrink: 0;
42	  width: var(--icon-md);
43	  height: var(--icon-md);
44	  border: 1px solid var(--border-default);
45	  border-radius: var(--shape-xs-radius);
46	  display: flex;
47	  align-items: center;
48	  justify-content: center;
49	  background: transparent;
50	  transition: background var(--motion-instant-duration), border-color var(--motion-instant-duration);
51	}
52	
53	:where([data-aria-container] [aria-selected="true"] .item-indicator--checkbox) {
54	  border-color: var(--tone-primary-base);
55	  background: var(--tone-primary-base);
56	}
57	
58	:where([data-aria-container] .item-indicator--checkbox-icon) {
59	  width: var(--icon-sm);
60	  height: var(--icon-sm);
61	  color: var(--tone-primary-foreground);
62	}
63	
64	/* ── Radio indicator (circle + dot) ── */
65	
66	:where([data-aria-container] .item-indicator--radio) {
67	  flex-shrink: 0;
68	  width: var(--icon-md);
69	  height: var(--icon-md);
70	  border: 1px solid var(--border-default);
71	  border-radius: 50%;
72	  display: flex;
73	  align-items: center;
74	  justify-content: center;
75	  transition: border-color var(--motion-instant-duration);
76	}
77	
78	:where([data-aria-container] [aria-checked="true"] .item-indicator--radio) {
79	  border-color: var(--tone-primary-base);
80	}
81	
82	:where([data-aria-container] .item-indicator--radio-dot) {
83	  width: var(--space-sm);
84	  height: var(--space-sm);
85	  border-radius: 50%;
86	  background: var(--tone-primary-base);
87	  transform: scale(0);
88	  transition: transform var(--motion-instant-duration);
89	}
90	
91	:where([data-aria-container] [aria-checked="true"] .item-indicator--radio-dot) {
92	  transform: scale(1);
93	}
94	
95	/* ── Switch indicator (track + thumb) ── */
96	
97	:where([data-aria-container] .item-indicator--switch) {
98	  flex-shrink: 0;
99	  width: var(--switch-width);
100	  height: var(--switch-height);
101	  border-radius: var(--shape-pill-radius);
102	  background: var(--surface-overlay);
103	  border: 1px solid var(--border-default);
104	  position: relative;
105	  transition: background var(--motion-normal-duration) var(--motion-normal-easing),
106	              border-color var(--motion-normal-duration) var(--motion-normal-easing);
107	}
108	
109	:where([data-aria-container] [aria-checked="true"] .item-indicator--switch) {
110	  background: var(--tone-primary-base);
111	  border-color: var(--tone-primary-base);
112	}
113	
114	:where([data-aria-container] .item-indicator--switch-thumb) {
115	  position: absolute;
116	  top: 1px;
117	  left: 1px;
118	  width: var(--icon-sm);
119	  height: var(--icon-sm);
120	  border-radius: 50%;
121	  background: var(--text-secondary);
122	  box-shadow: var(--shadow-sm);
123	  transition: transform var(--motion-normal-duration) var(--motion-normal-easing),
124	              background var(--motion-normal-duration) var(--motion-normal-easing);
125	}
126	
127	:where([data-aria-container] [aria-checked="true"] .item-indicator--switch-thumb) {
128	  background: var(--tone-primary-foreground);
129	  transform: translateX(calc(var(--switch-width) - var(--icon-sm) - 4px));
130	}
131	
132	/* ── Toggle text indicator (On/Off) ── */
133	
134	:where([data-aria-container] .item-indicator--toggle) {
135	  color: var(--text-muted);
136	  font-size: var(--type-body-size);
137	}
138	
139	:where([data-aria-container] [aria-checked="true"] .item-indicator--toggle) {
140	  color: var(--tone-success-base);
141	}
142	
143	/* ── ToggleGroup text indicator ── */
144	
145	:where([data-aria-container] .item-indicator--toggle-group) {
146	  color: var(--text-muted);
147	}
148	
149	:where([data-aria-container] [aria-selected="true"] .item-indicator--toggle-group) {
150	  color: var(--tone-primary-base);
151	}
152	
153	/* ── Sort indicator ── */
154	
155	:where([data-aria-container] .item-indicator--sort) {
156	  flex-shrink: 0;
157	  display: flex;
158	  align-items: center;
159	  justify-content: center;
160	  font-size: var(--type-body-size);
161	  color: var(--text-muted);
162	}
163	
164	:where([data-aria-container] [aria-sort="ascending"] .item-indicator--sort),
165	:where([data-aria-container] [aria-sort="descending"] .item-indicator--sort) {
166	  color: var(--tone-primary-base);
167	}
168	
169	/* ── Spinner indicator ── */
170	
171	@keyframes indicator-spin {
172	  to { transform: rotate(360deg); }
173	}
174	
175	:where(.item-indicator--spinner) {
176	  display: inline-flex;
177	  align-items: center;
178	  justify-content: center;
179	  color: var(--tone-primary-base);
180	  animation: indicator-spin var(--motion-slow-duration, 0.8s) linear infinite;
181	}
182	
183	:where(.item-indicator--spinner-sm) { font-size: var(--icon-sm); }
184	:where(.item-indicator--spinner-md) { font-size: var(--icon-md); }
185	:where(.item-indicator--spinner-lg) { font-size: var(--icon-lg, var(--space-2xl)); }
186	
187	/* ── Progress indicator ── */
188	
189	:where(.item-indicator--progress) {
190	  width: 100%;
191	  height: var(--space-xs);
192	  background: var(--surface-overlay);
193	  border-radius: var(--shape-pill-radius);
194	  overflow: hidden;
195	}
196	
197	:where(.item-indicator--progress-fill) {
198	  height: 100%;
199	  background: var(--tone-primary-base);
200	  border-radius: var(--shape-pill-radius);
201	  transition: width var(--motion-normal-duration) var(--motion-normal-easing);
202	}
203	
204	/* ── Skeleton indicator ── */
205	
206	@keyframes indicator-shimmer {
207	  0% { background-position: -200% 0; }
208	  100% { background-position: 200% 0; }
209	}
210	
211	:where(.item-indicator--skeleton) {
212	  border-radius: var(--shape-xs-radius);
213	  background: linear-gradient(
214	    90deg,
215	    var(--surface-overlay) 25%,
216	    var(--surface-hover) 50%,
217	    var(--surface-overlay) 75%
218	  );
219	  background-size: 200% 100%;
220	  animation: indicator-shimmer 1.5s ease-in-out infinite;
221	}
222	
223	/* ── Status indicator ── */
224	
225	:where(.item-indicator--status) {
226	  display: inline-block;
227	  width: var(--space-sm);
228	  height: var(--space-sm);
229	  border-radius: 50%;
230	  flex-shrink: 0;
231	}
232	
233	:where(.item-indicator--status-success) { background: var(--tone-success-base); }
234	:where(.item-indicator--status-error) { background: var(--tone-destructive-base); }
235	:where(.item-indicator--status-warning) { background: var(--tone-warning-base, #f59e0b); }
236	:where(.item-indicator--status-info) { background: var(--tone-primary-base); }
237	
238	/* ── Page indicator (pagination dots) ── */
239	
240	:where(.item-indicator--page) {
241	  display: inline-flex;
242	  align-items: center;
243	  gap: var(--space-xs);
244	}
245	
246	:where(.item-indicator--page-dot) {
247	  width: var(--space-sm);
248	  height: var(--space-sm);
249	  border-radius: 50%;
250	  background: var(--border-default);
251	  transition: background var(--motion-instant-duration);
252	}
253	
254	:where(.item-indicator--page-dot-active) {
255	  background: var(--tone-primary-base);
256	}
257	
258	/* ── Direction indicator ── */
259	
260	:where(.item-indicator--direction) {
261	  display: inline-flex;
262	  align-items: center;
263	  justify-content: center;
264	  font-size: var(--type-body-size);
265	  color: var(--text-muted);
266	}
267	
268	/* ── Step indicator ── */
269	
270	:where(.item-indicator--step) {
271	  display: inline-flex;
272	  align-items: center;
273	  justify-content: center;
274	  width: var(--icon-md);
275	  height: var(--icon-md);
276	  border-radius: 50%;
277	  border: 1px solid var(--border-default);
278	  font-size: var(--type-caption-size);
279	  font-weight: var(--weight-semi);
280	  color: var(--text-secondary);
281	  flex-shrink: 0;
282	}
283	
284	:where(.item-indicator--step-completed) {
285	  background: var(--tone-primary-base);
286	  border-color: var(--tone-primary-base);
287	  color: var(--tone-primary-foreground);
288	}
289	
290	/* ── Badge indicator ── */
291	
292	:where(.item-indicator--badge) {
293	  display: inline-flex;
294	  align-items: center;
295	  justify-content: center;
296	  min-width: var(--icon-sm);
297	  height: var(--icon-sm);
298	  padding: 0 var(--space-xs);
299	  border-radius: var(--shape-pill-radius);
300	  background: var(--tone-destructive-base);
301	  color: var(--tone-primary-foreground);
302	  font-size: var(--type-caption-size);
303	  font-weight: var(--weight-semi);
304	  line-height: 1;
305	  flex-shrink: 0;
306	}
307	
308	/* ── Overflow indicator ── */
309	
310	:where(.item-indicator--overflow) {
311	  font-size: var(--type-caption-size);
312	  color: var(--text-muted);
313	  white-space: nowrap;
314	  flex-shrink: 0;
315	}
316	
317	/* ── Grip indicator ── */
318	
319	:where(.item-indicator--grip) {
320	  display: inline-flex;
321	  align-items: center;
322	  justify-content: center;
323	  color: var(--text-muted);
324	  font-size: var(--type-body-size);
325	  cursor: grab;
326	}
327	
328	/* ── Tree connector ── */
329	
330	:where(.item-indicator--tree-connector) {
331	  display: inline-block;
332	  width: var(--space-lg);
333	  height: 100%;
334	  position: relative;
335	  flex-shrink: 0;
336	}
337	
338	:where(.item-indicator--tree-connector)::before {
339	  content: '';
340	  position: absolute;
341	  left: 50%;
342	  top: 0;
343	  bottom: 0;
344	  width: 1px;
345	  background: var(--border-subtle);
346	}
347	
348	:where(.item-indicator--tree-connector)::after {
349	  content: '';
350	  position: absolute;
351	  left: 50%;
352	  top: 50%;
353	  width: 50%;
354	  height: 1px;
355	  background: var(--border-subtle);
356	}
357	
358	:where(.item-indicator--tree-connector-last)::before {
359	  bottom: 50%;
360	}
361	
362	/* ── Separator indicator ── */
363	
364	:where(.item-indicator--separator) {
365	  flex-shrink: 0;
366	  background: var(--border-subtle);
367	}
368	
369	:where(.item-indicator--separator[aria-orientation="horizontal"]),
370	:where(.item-indicator--separator:not([aria-orientation])) {
371	  height: 1px;
372	  width: 100%;
373	}
374	
375	:where(.item-indicator--separator[aria-orientation="vertical"]) {
376	  width: 1px;
377	  align-self: stretch;
378	}
379

1	/* ② 2026-03-26-component-styling-rules-prd.md */
2	
3	.empty {
4	  gap: var(--space-sm);
5	  color: var(--text-muted);
6	}
7

1	/* SplitPane — ratio-based resizable split container
2	   // ② 2026-03-26-component-styling-rules-prd.md */
3	
4	.separator {
5	  transition: background var(--motion-instant-duration) var(--motion-instant-easing);
6	  --_bg: var(--border-default);
7	  --_bg-hover: var(--focus);
8	  background: var(--_bg);
9	}
10	
11	.separatorH {
12	  width: var(--space-xs);
13	  cursor: col-resize;
14	}
15	
16	.separatorV {
17	  height: var(--space-xs);
18	  cursor: row-resize;
19	}
20

1	/* ── TabGroup — JetBrains Islands style ──
2	   // ② 2026-03-26-component-styling-rules-prd.md */
3	
4	.tabBar {
5	  gap: var(--space-2xs);
6	  padding: var(--space-2xs) var(--space-sm);
7	  background: var(--surface-sunken);
8	}
9	
10	/* ── Tab ── */
11	.tab {
12	  gap: var(--space-xs);
13	  padding: var(--shape-xs-py) var(--shape-sm-px);
14	  border-radius: var(--shape-sm-radius);
15	  transition:
16	    background var(--motion-instant-duration) var(--motion-instant-easing),
17	    color var(--motion-instant-duration) var(--motion-instant-easing);
18	  --_bg: transparent;
19	  --_bg-hover: var(--surface-default);
20	  --_fg: var(--text-muted);
21	  background: var(--_bg);
22	  color: var(--_fg);
23	}
24	
25	.tab[aria-selected="true"] {
26	  --_bg: var(--surface-raised);
27	  --_fg: var(--text-primary);
28	}
29	
30	.tabPreview {
31	  font-style: italic;
32	}
33	
34	/* ── Close button ── */
35	.tabClose {
36	  border-radius: var(--shape-xs-radius);
37	  padding: var(--space-2xs);
38	  opacity: 0;
39	  color: var(--text-muted);
40	  transition: opacity var(--motion-instant-duration) var(--motion-instant-easing);
41	  --_bg: transparent;
42	  --_bg-hover: var(--surface-overlay);
43	}
44	
45	.tab:hover .tabClose,
46	.tab[aria-selected="true"] .tabClose {
47	  opacity: 0.6;
48	}
49	
50

1	/* ── Block 1: base ── */
2	.header {
3	  padding: var(--shape-sm-py) var(--shape-sm-px);
4	  font-size: var(--type-body-size);
5	  font-weight: var(--weight-semi);
6	  font-family: var(--type-body-family);
7	  line-height: var(--type-body-line-height);
8	  color: var(--text-primary);
9	  user-select: none;
10	}
11	
12	.header + .panel {
13	  border-bottom: 1px solid var(--border-subtle);
14	}
15	
16	.chevron {
17	  color: var(--text-muted);
18	  transition: transform var(--motion-normal-duration) var(--motion-normal-easing);
19	}
20	
21	.chevronExpanded {
22	  transform: rotate(90deg);
23	}
24	
25	.item {
26	  padding: var(--shape-sm-py) var(--shape-sm-px);
27	  padding-left: var(--space-2xl);
28	  font-size: var(--type-body-size);
29	  font-weight: var(--type-body-weight);
30	  font-family: var(--type-body-family);
31	  line-height: var(--type-body-line-height);
32	  color: var(--text-secondary);
33	}
34

1	/* ── Menubar — 3-block recipe ── */
2	
3	/* ═══ Block 1: base ═══ */
4	.link {
5	  gap: var(--space-xs);
6	  padding: var(--shape-xs-py) var(--shape-sm-px);
7	  font-size: var(--type-body-size);
8	  font-weight: var(--type-body-weight);
9	  line-height: var(--type-body-line-height);
10	  color: var(--text-primary);
11	  cursor: default;
12	  border: 2px solid transparent;
13	}
14	
15	.indicator {
16	  color: var(--text-muted);
17	}
18	
19	/* ── submenu panel ── */
20	
21	.submenu {
22	  padding: var(--space-xs) 0;
23	  margin: 0;
24	  min-width: 180px;
25	  background: var(--surface-overlay);
26	  border: var(--border-width) solid var(--border-default);
27	  border-radius: var(--shape-xs-radius);
28	  box-shadow: var(--shadow-md);
29	  z-index: 1;
30	}
31	
32	.submenuRoot {
33	  composes: submenu;
34	  top: 100%;
35	  left: 0;
36	}
37	
38	.submenuNested {
39	  composes: submenu;
40	  top: calc(var(--space-xs) * -1);
41	  left: 100%;
42	}
43	
44	/* ═══ Block 2: variant ═══ */
45	
46	.link:focus {
47	  border-color: var(--focus);
48	}
49	
50	.link:is([data-focused='true']):focus {
51	  background: var(--bg-hover);
52	}
53	
54	.link:is([aria-expanded='true']) {
55	  background: var(--bg-hover);
56	}
57

1	/* Composer — multiline input with Enter-to-submit */
2	
3	/* --- Editable wrapper --- */
4	
5	.inputWrap {
6	  border: 1px solid var(--border-default);
7	  border-radius: var(--shape-md-radius);
8	  background: var(--surface-base);
9	  transition:
10	    border-color var(--motion-instant-duration) var(--motion-instant-easing),
11	    box-shadow var(--motion-instant-duration) var(--motion-instant-easing);
12	}
13	
14	.inputWrap:focus-within {
15	  border-color: var(--tone-primary-base);
16	}
17	
18	.inputWrap[data-disabled] {
19	  opacity: 0.4;
20	  pointer-events: none;
21	}
22	
23	/* --- Editor area (position context for overlay) --- */
24	
25	/* --- Editable content --- */
26	
27	.editor {
28	  min-height: calc(var(--leading-snug) * 1em + var(--shape-sm-py) * 2);
29	  padding: var(--space-sm) var(--space-md);
30	  font-size: var(--type-body-size);
31	  line-height: var(--leading-snug);
32	  font-family: inherit;
33	  color: var(--text-primary);
34	  white-space: pre-wrap;
35	  word-break: break-word;
36	}
37	
38	.editor[data-overlay] {
39	  color: transparent;
40	  caret-color: var(--text-primary);
41	}
42	
43	/* --- Placeholder via :empty --- */
44	
45	.editor:empty::before {
46	  content: attr(data-placeholder);
47	  color: var(--text-muted);
48	  pointer-events: none;
49	}
50	
51	/* --- Ghost text overlay --- */
52	
53	.overlay {
54	  padding: var(--space-sm) var(--space-md);
55	  font-size: var(--type-body-size);
56	  line-height: var(--leading-snug);
57	  font-family: inherit;
58	  white-space: pre-wrap;
59	  word-break: break-word;
60	}
61	
62	.commandMatch {
63	  color: var(--tone-primary-base);
64	}
65	
66	.overlayNormal {
67	  color: var(--text-primary);
68	}
69	
70	.ghost {
71	  color: var(--text-muted);
72	}
73	
74	/* --- Suggestion popup (above input, Slack-style) --- */
75	
76	.suggestionList {
77	  bottom: 100%;
78	  left: 0;
79	  right: 0;
80	  margin: 0;
81	  padding: var(--space-xs) 0;
82	  background: var(--surface-raised);
83	  border: 1px solid var(--border-subtle);
84	  border-radius: var(--shape-md-radius);
85	  box-shadow: var(--shadow-md);
86	  max-height: calc(var(--type-body-size) * var(--leading-snug) * 8 + var(--space-xs) * 2);
87	  z-index: 1;
88	}
89	
90	.suggestionItem {
91	  padding: var(--space-xs) var(--space-md);
92	  font-size: var(--type-body-size);
93	  line-height: var(--leading-snug);
94	  color: var(--text-secondary);
95	}
96	
97	.suggestionItem:hover {
98	  background: var(--bg-hover);
99	  color: var(--text-primary);
100	}
101	
102	.suggestionItem[data-selected] {
103	  background: var(--bg-active);
104	  color: var(--text-bright);
105	}
106

1	/* StreamFeed — streaming feed container
2	   ② 2026-03-25-stream-feed-prd.md */
3	
4	/* --- Container: :where() for specificity 0 defaults --- */
5	
6	:where(.feed) {
7	  gap: var(--space-lg);
8	}
9	
10	/* --- Entry animation --- */
11	
12	.entry {
13	  animation: fadeSlideIn var(--motion-enter-duration) var(--motion-enter-easing) both;
14	}
15	
16	@keyframes fadeSlideIn {
17	  from {
18	    opacity: 0;
19	    transform: translateY(var(--space-sm));
20	  }
21	  to {
22	    opacity: 1;
23	    transform: translateY(0);
24	  }
25	}
26	
27	/* --- Streaming indicator --- */
28	
29	.streaming {
30	  gap: var(--space-sm);
