36	
37	/* ── Card ── */
38	.card {
39	  background: var(--surface-default);
40	  border: 1px solid var(--border-subtle);
41	  border-radius: var(--shape-xl-radius);
42	  padding: var(--shape-xl-py) var(--shape-xl-px);
43	  font-size: var(--type-body-size);
