81	  text-transform: none;
82	  letter-spacing: 0;
83	  padding: var(--space-xs) 0;
84	  white-space: nowrap;
85	  overflow: hidden;
86	  text-overflow: ellipsis;
87	  position: relative;
88	}
89	
90	.board[data-compact] .columnHeader::after {
91	  content: '';
92	  position: absolute;
93	  bottom: 0;
94	  left: 0;
95	  height: 2px;
96	  width: calc(var(--_loc-ratio, 0) * 100%);
97	  background: var(--tone-primary-dim);
98	  border-radius: var(--border-width);
99	  opacity: 0.6;
100	}
101	
102	.board[data-compact] .card {
103	  display: flex;
104	  align-items: baseline;
105	  gap: var(--space-xs);
106	  padding: var(--space-xs) var(--space-sm);
107	  border: none;
108	  border-radius: var(--shape-xs-radius);
109	  font-size: var(--type-caption-size);
110	  line-height: var(--leading-normal);
111	  flex-shrink: 0;
112	}
113	
114	/* ── Card title (truncate) ── */
115	.cardTitle { text-overflow: ellipsis; }
116	
117	/* ── Card subtitle (LOC etc.) ── */
118	.cardSubtitle {
119	  font-size: var(--type-caption-size);
120	  color: var(--text-muted);
121	  margin-left: auto;
122	  font-variant-numeric: tabular-nums;
123	}
124	
125	/* ── Extension color indicator (inset shadow, border:none 호환) ── */
126	
127	.board[data-compact] .card[data-ext="ts"] { box-shadow: inset 3px 0 0 var(--tone-primary-base); }
128	.board[data-compact] .card[data-ext="tsx"] { box-shadow: inset 3px 0 0 var(--focus); }
129	.board[data-compact] .card[data-ext="css"] { box-shadow: inset 3px 0 0 var(--tone-destructive-base); }
130	.board[data-compact] .card[data-ext="md"],
131	.board[data-compact] .card[data-ext="mdx"] { box-shadow: inset 3px 0 0 var(--tone-positive-base); }
132	.board[data-compact] .card[data-ext="json"],
133	.board[data-compact] .card[data-ext="yaml"],
134	.board[data-compact] .card[data-ext="yml"] { box-shadow: inset 3px 0 0 var(--tone-warning-base); }
135	
136	/* ── Weight hints (LOC-based file size indicator) ── */
137	
138	.board[data-compact] .card[data-weight="md"] {
139	  font-weight: var(--weight-medium);
140	}
141	
142	.board[data-compact] .card[data-weight="lg"] {
143	  font-weight: var(--weight-semi);
144	  color: var(--text-bright);
145	  background: color-mix(in srgb, var(--tone-warning-base) 12%, var(--surface-default));
146	}
147	
148	/* ── Hub indicator (high importedBy — load-bearing files) ── */
149	
150	.board[data-compact] .card[data-hub] {
151	  border-inline-start-width: var(--space-xs);
152	  border-inline-start-color: var(--tone-info-base);
153	  background: color-mix(in srgb, var(--tone-info-base) 6%, var(--surface-default));
154	}
155	
156	/* ── Dependency count colors in subtitle ── */
157	
158	.depUp {
159	  color: var(--tone-positive-base);
160	  font-weight: var(--weight-medium);
161	}
162	
163	.depDown {
164	  color: var(--tone-primary-base);
165	  font-weight: var(--weight-medium);
166	}
167	
168	/* ── Dependency highlight — dim unrelated, brighten related ── */
169	
170	.board[data-compact][data-has-highlight] .card:not([data-highlight]):not([data-focused]) {
171	  opacity: 0.25;
172	}
173	
174	.board[data-compact] .card[data-highlight="up"] {
175	  box-shadow: inset 3px 0 0 var(--tone-positive-base);
176	}
177	
178	.board[data-compact] .card[data-highlight="down"] {
179	  box-shadow: inset 3px 0 0 var(--tone-primary-base);
180	}
181	
182	/* ── Focus/Selection — override .card background ── */
183	
184	.card[data-focused] {
185	  background: var(--tone-primary-dim);
186	  color: var(--text-bright);
187	}
188	
189	.card[aria-selected="true"] {
190	  background: var(--selection);
191	  color: var(--text-bright);
192	}
