1	import React, { useRef, useEffect, useMemo } from 'react'
2	import styles from './Kanban.module.css'
3	import { ROOT_ID } from '../store/types'
4	import { useAria } from '../primitives/useAria'
5	import { AriaInternalContext } from '../primitives/AriaInternalContext'
6	import { AriaItemContext, Aria } from '../primitives/aria'
7	import { kanban as kanbanBehavior } from './kanbanPreset'
8	import { getChildren, getEntity } from '../store/createStore'
9	import type { AriaComponentProps } from './types'
10	
11	interface KanbanProps extends AriaComponentProps {
12	  highlightUp?: Set<string>
13	  highlightDown?: Set<string>
14	  compact?: boolean
15	}
16	
17	function FocusDiv({ focused, children, ...props }: { focused: boolean; children: React.ReactNode } & React.HTMLAttributes<HTMLDivElement>) {
18	  const ref = useRef<HTMLDivElement>(null)
19	  useEffect(() => {
20	    if (focused && ref.current) {
21	      ref.current.scrollIntoView?.({ block: 'nearest', inline: 'nearest' })
22	    }
23	  }, [focused])
24	  return <div ref={ref} data-focused={focused || undefined} {...props}>{children}</div>
25	}
26	
27	export function Kanban({
28	  data,
29	  plugins = [],
30	  onChange,
31	  onActivate,
32	  onFocusChange,
33	  highlightUp,
34	  highlightDown,
35	  compact = false,
36	  'aria-label': ariaLabel,
37	}: KanbanProps) {
38	  // onActivate가 있으면 Enter를 activate로 override (기본은 rename)
39	  const keyMap = useMemo(() => onActivate ? { Enter: (ctx: { activate: () => void }) => ctx.activate() } : undefined, [onActivate])
40	  const aria = useAria({ pattern: kanbanBehavior, data, plugins, keyMap, onChange, onActivate, onFocusChange })
41	  const store = aria.getStore()
42	  const columns = getChildren(store, ROOT_ID)
43	
44	  // Column LOC ratios for visual bar
45	  const maxColLoc = useMemo(() => {
46	    let max = 0
47	    for (const colId of columns) {
48	      const loc = (getEntity(store, colId)?.data as Record<string, unknown> | undefined)?.totalLoc as number | undefined
49	      if (loc && loc > max) max = loc
50	    }
51	    return max
52	  }, [store, columns])
53	
54	  return (
55	    <AriaInternalContext.Provider value={{ ...aria, pattern: kanbanBehavior }}>
56	      <div
57	        role={kanbanBehavior.role}
58	        aria-label={ariaLabel}
59	        data-aria-container=""
60	        className={`flex-row gap-md overflow-x-auto ${styles.board}`}
61	        data-compact={compact || undefined}
62	        data-has-highlight={(highlightUp?.size || highlightDown?.size) ? '' : undefined}
63	        {...(aria.containerProps as React.HTMLAttributes<HTMLDivElement>)}
64	      >
65	        {columns.map((colId) => {
66	          const colEntity = getEntity(store, colId)
67	          if (!colEntity) return null
68	          const colState = aria.getNodeState(colId)
69	          const colProps = aria.getNodeProps(colId)
70	          const cards = getChildren(store, colId)
71	          const colData = colEntity.data as Record<string, unknown> | undefined
72	          const colTitle = colData?.title as string ?? ''
73	          const totalLoc = colData?.totalLoc as number | undefined
74	
75	          const locRatio = totalLoc && maxColLoc ? totalLoc / maxColLoc : 0
76	
77	          return (
78	            <div key={colId} className={`flex-col gap-xs ${styles.column}`}>
79	              {/* Column header */}
80	              <FocusDiv
81	                focused={colState.focused}
82	                className={`flex-row items-center gap-sm ${styles.columnHeader}`}
83	                title={`${colTitle}\n${cards.length} files${totalLoc ? ` · ${totalLoc} lines` : ''}`}
84	                style={locRatio > 0 ? { '--_loc-ratio': locRatio } as React.CSSProperties : undefined}
85	                {...(colProps as React.HTMLAttributes<HTMLDivElement>)}
86	              >
87	                <AriaItemContext.Provider value={{ nodeId: colId, focused: colState.focused, renaming: !!colState.renaming }}>
88	                  <span>{colTitle}</span>
89	                  <span className={styles.columnCount}>{cards.length}{totalLoc != null && totalLoc > 0 ? ` · ${totalLoc}L` : ''}</span>
90	                </AriaItemContext.Provider>
91	              </FocusDiv>
92	
93	              {/* Cards */}
94	              {cards.map((cardId) => {
95	                const cardEntity = getEntity(store, cardId)
96	                if (!cardEntity) return null
97	                const cardState = aria.getNodeState(cardId)
98	                const cardProps = aria.getNodeProps(cardId)
99	                const cardData = cardEntity.data as Record<string, unknown> | undefined
100	                const cardTitle = cardData?.title as string ?? ''
101	                const cardSubtitle = cardData?.subtitle as string | undefined
102	                const cardTooltip = cardData?.tooltip as string | undefined
103	                const cardWeight = cardData?.weight as string | undefined
104	                const cardExt = cardData?.ext as string | undefined
105	                const cardDepUp = cardData?.depUp as number | undefined
106	                const cardDepDown = cardData?.depDown as number | undefined
107	                const hlDir = highlightUp?.has(cardId) ? 'up' : highlightDown?.has(cardId) ? 'down' : undefined
108	                const isHub = cardDepUp != null && cardDepUp >= 20
109	
110	                return (
111	                  <FocusDiv
112	                    key={cardId}
113	                    focused={cardState.focused}
114	                    className={styles.card}
115	                    data-hub={isHub || undefined}
116	                    title={cardTooltip ?? cardTitle}
117	                    data-weight={cardWeight || undefined}
118	                    data-ext={cardExt || undefined}
119	                    data-highlight={hlDir}
120	                    data-source={(cardData?.sourceId as string) || undefined}
121	                    {...(cardProps as React.HTMLAttributes<HTMLDivElement>)}
122	                  >
123	                    <AriaItemContext.Provider value={{ nodeId: cardId, focused: cardState.focused, renaming: !!cardState.renaming }}>
124	                      <span className={`overflow-hidden whitespace-nowrap min-w-0 ${styles.cardTitle}`}><Aria.Editable field="title">{cardTitle}</Aria.Editable></span>
125	                      {(cardSubtitle || cardDepUp != null || cardDepDown != null) && (
126	                        <span className={`shrink-0 ${styles.cardSubtitle}`}>
127	                          {cardSubtitle}
128	                          {cardDepUp != null && cardDepUp > 0 && <span className={styles.depUp}> ↑{cardDepUp}</span>}
129	                          {cardDepDown != null && cardDepDown > 0 && <span className={styles.depDown}> ↓{cardDepDown}</span>}
130	                        </span>
131	                      )}
132	                    </AriaItemContext.Provider>
133	                  </FocusDiv>
134	                )
135	              })}
136	            </div>
137	          )
138	        })}
139	      </div>
140	    </AriaInternalContext.Provider>
141	  )
142	}
