1	// ② 2026-03-30-composer-ghost-text-prd.md
2	import { useRef, useCallback, useEffect, useImperativeHandle, forwardRef, useMemo } from 'react'
3	import styles from './Composer.module.css'
4	import { useAria } from '../primitives/useAria'
5	import { combobox as comboboxPattern } from '../pattern/roles/combobox'
6	import { focusCommands } from '../axis/navigate'
7	import { ROOT_ID } from '../store/types'
8	import type { NormalizedData } from '../store/types'
9	
10	export interface ComposerProps {
11	  onSubmit?: (text: string) => void
12	  disabled?: boolean
13	  placeholder?: string
14	  commandHighlight?: number
15	  overlayText?: string
16	  suggestions?: string[]
17	  onCommandSelect?: (cmd: string) => void
18	  onDismiss?: () => void
19	  onTextChange?: (text: string) => void
20	}
21	
22	export interface ComposerHandle {
23	  setText: (text: string) => void
24	  getText: () => string
25	}
26	
27	function suggestionsToData(items: string[]): NormalizedData {
28	  const entities: Record<string, { id: string; data: { label: string } }> = {}
29	  for (const cmd of items) {
30	    entities[cmd] = { id: cmd, data: { label: cmd } }
31	  }
32	  return { entities, relationships: { [ROOT_ID]: items } }
33	}
34	
35	const EMPTY_DATA: NormalizedData = { entities: {}, relationships: { [ROOT_ID]: [] } }
36	
37	export const Composer = forwardRef<ComposerHandle, ComposerProps>(function Composer(
38	  {
39	    onSubmit, disabled, placeholder = 'Send a message...',
40	    commandHighlight = 0, overlayText = '',
41	    suggestions, onCommandSelect, onDismiss, onTextChange,
42	  },
43	  fwdRef,
44	) {
45	  const ref = useRef<HTMLDivElement>(null)
46	  const isComposingRef = useRef(false)
47	
48	  useEffect(() => { ref.current?.focus() }, [])
49	
50	  const getText = useCallback(() => ref.current?.textContent ?? '', [])
51	
52	  const clear = useCallback(() => {
53	    if (ref.current) {
54	      ref.current.textContent = ''
55	      ref.current.focus()
56	    }
57	  }, [])
58	
59	  const setText = useCallback((text: string) => {
60	    if (!ref.current) return
61	    ref.current.textContent = text
62	    const range = document.createRange()
63	    const sel = window.getSelection()
64	    range.selectNodeContents(ref.current)
65	    range.collapse(false)
66	    sel?.removeAllRanges()
67	    sel?.addRange(range)
68	  }, [])
69	
70	  useImperativeHandle(fwdRef, () => ({ setText, getText }), [setText, getText])
71	
72	  const fireTextChange = useCallback(() => {
73	    if (!isComposingRef.current) onTextChange?.(getText())
74	  }, [getText, onTextChange])
75	
76	  // --- os combobox for suggestion popup ---
77	
78	  const hasSuggestions = !!suggestions && suggestions.length > 0
79	  const data = useMemo(() => hasSuggestions ? suggestionsToData(suggestions!) : EMPTY_DATA, [suggestions, hasSuggestions])
80	
81	  const aria = useAria({
82	    pattern: comboboxPattern({ selectionMode: 'single' }),
83	    data,
84	    autoFocus: false,
85	  })
86	
87	  // Focus first suggestion when list appears or changes
88	  const prevSuggestionsRef = useRef<string[] | undefined>(undefined)
89	  useEffect(() => {
90	    if (hasSuggestions && suggestions !== prevSuggestionsRef.current) {
91	      aria.dispatch(focusCommands.setFocus(suggestions![0]))
92	    }
93	    prevSuggestionsRef.current = suggestions
94	  }, [suggestions, hasSuggestions, aria])
95	
96	  const focusedCmd = aria.focused
97	  const typedCmd = overlayText.startsWith('/') ? overlayText.slice(1) : ''
98	  const ghostText = (hasSuggestions && focusedCmd && focusedCmd.startsWith(typedCmd))
99	    ? focusedCmd.slice(typedCmd.length)
100	    : ''
101	
102	  // Merge pattern keydown with our handlers
103	  const patternKeyDown = (aria.containerProps as Record<string, unknown>).onKeyDown as ((e: React.KeyboardEvent) => void) | undefined
104	
105	  const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLDivElement>) => {
106	    if (hasSuggestions) {
107	      if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Home' || e.key === 'End') {
108	        // Let pattern handle navigation
109	        patternKeyDown?.(e)
110	        return
111	      }
112	      if (e.key === 'Tab' || (e.key === 'Enter' && !e.shiftKey && !isComposingRef.current)) {
113	        e.preventDefault()
114	        if (focusedCmd) onCommandSelect?.(focusedCmd)
115	        return
116	      }
117	      if (e.key === 'Escape') {
118	        onDismiss?.()
119	        return
120	      }
121	    }
122	
123	    // Normal Composer handlers (no popup)
124	    if (e.key === 'Enter' && !e.shiftKey && !isComposingRef.current) {
125	      e.preventDefault()
126	      const trimmed = getText().trim()
127	      if (trimmed && onSubmit && !disabled) {
128	        onSubmit(trimmed)
129	        clear()
130	        onTextChange?.('')
131	      }
132	    }
133	    if (e.key === 'Tab' && ghostText && onCommandSelect && focusedCmd) {
134	      e.preventDefault()
135	      onCommandSelect(focusedCmd)
136	    }
137	    if (e.key === 'Escape' && ghostText && onDismiss) {
138	      onDismiss()
139	    }
140	  }, [getText, clear, onSubmit, disabled, hasSuggestions, ghostText, focusedCmd, patternKeyDown, onCommandSelect, onDismiss, onTextChange])
141	
142	  const handleCompositionStart = useCallback(() => { isComposingRef.current = true }, [])
143	  const handleCompositionEnd = useCallback(() => {
144	    isComposingRef.current = false
145	    fireTextChange()
146	  }, [fireTextChange])
147	
148	  const hasOverlay = !disabled && (commandHighlight > 0 || !!ghostText)
149	
150	  return (
151	    <div className={"flex-row shrink-0"}>
152	      <div className={`flex-1 relative ${styles.inputWrap}`} data-disabled={disabled || undefined}>
153	        {hasSuggestions && (
154	          <ul className={`absolute list-none overflow-y-auto ${styles.suggestionList}`} role="listbox" aria-label="Command suggestions">
155	            {suggestions!.map(cmd => {
156	              const nodeProps = aria.getNodeProps(cmd) as Record<string, unknown>
157	              const state = aria.getNodeState(cmd)
158	              return (
159	                <li
160	                  key={cmd}
161	                  ref={state.focused ? el => el?.scrollIntoView({ block: 'nearest' }) : undefined}
162	                  role="option"
163	                  aria-selected={state.focused}
164	                  className={`cursor-pointer ${styles.suggestionItem}`}
165	                  data-selected={state.focused || undefined}
166	                  data-node-id={nodeProps['data-node-id'] as string}
167	                >
168	                  /{cmd}
169	                </li>
170	              )
171	            })}
172	          </ul>
173	        )}
174	        <div className={"relative"}>
175	          <div
176	            ref={ref}
177	            className={`overflow-y-auto outline-none ${styles.editor}`}
178	            contentEditable={!disabled}
179	            role="textbox"
180	            aria-multiline="true"
181	            aria-label={placeholder}
182	            data-placeholder={placeholder}
183	            data-overlay={hasOverlay || undefined}
184	            onKeyDown={handleKeyDown}
185	            onInput={fireTextChange}
186	            onCompositionStart={handleCompositionStart}
187	            onCompositionEnd={handleCompositionEnd}
188	            suppressContentEditableWarning
189	          />
190	          {hasOverlay && (
191	            <div className={`absolute inset-0 pointer-events-none ${styles.overlay}`} aria-hidden="true">
192	              {commandHighlight > 0 && (
193	                <span className={styles.commandMatch}>{overlayText.slice(0, commandHighlight)}</span>
194	              )}
195	              {commandHighlight > 0 && overlayText.length > commandHighlight && (
196	                <span className={styles.overlayNormal}>{overlayText.slice(commandHighlight)}</span>
197	              )}
198	              {ghostText && <span className={styles.ghost}>{ghostText}</span>}
199	            </div>
200	          )}
201	        </div>
202	      </div>
203	    </div>
204	  )
205	})
206

